#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <algorithm>
#include <string>
#include <map>
#include <iostream>
#include <cmath>
using namespace std;
const int N = 10005;
const int M = 105;
const int inf = 0x3f3f3f3f;
int a[M], b[N], f[N];
int main() {
    // freopen("data/1.in", "r", stdin);
    int n, m;
    scanf("%d%d", &n, &m);
    for (int i = 1; i <= m; i ++)
        scanf("%d", &a[i]);
    for (int i = 0; i < n; i ++)
        scanf("%d", &b[i]);

    memset(f, -0x3f, sizeof(f));
    f[0] = 0;
    for (int i = 1; i < n; i ++)
        for (int j = 1; j <= m; j ++)
            if (i - a[j] >= 0)
                f[i] = max(f[i], f[i - a[j]] + b[i - a[j]]);

    int ans = -inf;
    for (int i = 0; i < n; i ++)
        for (int j = 1; j <= m; j ++)
            if (i + a[j] >= n) {
                ans = max(ans, f[i] + b[i]);
                break ;
            }

    cout << ans << endl;
    return 0;
}

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <algorithm>
#include <string>
#include <map>
#include <iostream>
#include <cmath>
#include <vector>
using namespace std;
const int N = 305;
int fa[N], dep[N];
bool vis[N];
vector<int> ch[N];
int getdep(int x) {
    return x == 0 ? 0 : getdep(fa[x]) + 1;
}
void dfs(int x) {
    vis[x] = 1;
    for (int y : ch[x])
        dfs(y);
}
bool check(int x, int n, const vector<int> &vec) {
    for(int i = 0; i <= n; i ++)
        vis[i] = 0;
    dfs(x);
    for (int y : vec)
        if(! vis[y])
            return 0;
    return 1;
}
int main() {
    // freopen("data/1.in", "r", stdin);
    // freopen("tmp.txt", "w", stdout);
    int n;
    scanf("%d", &n);
    for(int i = 1; i < n; i ++) {
        scanf("%d", &fa[i]);
        ch[fa[i]].push_back(i);
    }
    for(int i = 1; i < n; i ++)
        dep[i] = getdep(i);

    int q;
    scanf("%d", &q);
    while(q --) {
        int m, mnd = n + 1;
        scanf("%d", &m);
        vector<int> vec(m);
        for(int i = 0; i < m; i ++) {
            scanf("%d", &vec[i]);
            mnd = min(mnd, dep[vec[i]]);
        }
        for (int i = n - 1; i >= 0; i --)
            if (dep[i] <= mnd && check(i, n, vec)) {
                printf("%d\n", i);
                break ;
            }
    }
    return 0;
}
